setup:
MUTATE {
  CREATE CONCEPT ?alice { TYPE "Person" NAME "Alice" SET FIELDS {key: "person:alice"} }
  CREATE CONCEPT ?dark { TYPE "Preference" NAME "Dark" }
  CREATE CONCEPT ?e1 { TYPE "Experience" NAME "First" SET ATTRIBUTES {goal: "learn", outcome_status: "success"} SET FACET "MnemonicState" {memory_strength: 0.8, salience: 0.5} }
  CREATE CONCEPT ?e2 { TYPE "Experience" NAME "Second" SET ATTRIBUTES {goal: "learn", outcome_status: "failure"} SET FACET "MnemonicState" {memory_strength: 0.4, salience: 0.5} }
  CREATE CONCEPT ?e3 { TYPE "Experience" NAME "Third" SET ATTRIBUTES {goal: "rest", outcome_status: "success"} SET FACET "MnemonicState" {memory_strength: 0.2, salience: 0.5} }
  ENSURE PROPOSITION ?p (?alice, "prefers", ?dark)
  CREATE ASSERTION ?a {
    SET FIELDS { proposition: ?p, asserted_by: ?alice, stance: "support", mode: "stated", confidence: 0.9 }
  }
}

cases.command:
MUTATE {
  CREATE CONCEPT ?fresh { TYPE "Experience" NAME "Fourth" SET ATTRIBUTES {goal: "learn", outcome_status: "success"} }
  ARCHIVE ?m WHERE { ?m CONCEPT {type: "Experience"} }
}
